/**
 * NUNYA Labs — Site JavaScript
 * Minimal. Accessible. Works without JS.
 */

document.addEventListener('DOMContentLoaded', function() {
  // Theme toggle
  const themeToggle = document.getElementById('themeToggle');
  const html = document.documentElement;
  
  // Check for saved theme preference or use time-based default
  const savedTheme = localStorage.getItem('nunya-theme');
  if (savedTheme) {
    html.setAttribute('data-theme', savedTheme);
  } else {
    // Time-based theme: dark 6PM-6AM, light 6AM-6PM (GMT/Accra)
    const hour = new Date().getHours();
    const timeTheme = (hour >= 18 || hour < 6) ? 'dark' : 'light';
    html.setAttribute('data-theme', timeTheme);
    localStorage.setItem('nunya-theme', timeTheme);
  }
  
  if (themeToggle) {
    themeToggle.addEventListener('click', function() {
      const currentTheme = html.getAttribute('data-theme');
      const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
      
      html.setAttribute('data-theme', newTheme);
      localStorage.setItem('nunya-theme', newTheme);
    });
  }
  
  // Mobile navigation toggle
  const navToggle = document.getElementById('navToggle');
  const navLinks = document.getElementById('navLinks');
  
  if (navToggle && navLinks) {
    navToggle.addEventListener('click', function() {
      navLinks.classList.toggle('active');
      
      const isExpanded = navLinks.classList.contains('active');
      navToggle.setAttribute('aria-expanded', isExpanded);
    });
    
    // Close menu when clicking a link
    navLinks.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        navLinks.classList.remove('active');
        navToggle.setAttribute('aria-expanded', 'false');
      });
    });
  }
  
  // Smooth scroll for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
      e.preventDefault();
      const target = document.querySelector(this.getAttribute('href'));
      if (target) {
        target.scrollIntoView({
          behavior: 'smooth',
          block: 'start'
        });
      }
    });
  });
  
  // Image slider for hero
  const sliderTrack = document.querySelector('.slider-track');
  const dots = document.querySelectorAll('.dot');
  const images = document.querySelectorAll('.slider-image');
  
  if (sliderTrack && dots.length > 0) {
    let currentSlide = 0;
    const totalSlides = images.length;
    
    function goToSlide(index) {
      images.forEach((img, i) => {
        img.classList.toggle('active', i === index);
      });
      dots.forEach((dot, i) => {
        dot.classList.toggle('active', i === index);
      });
      currentSlide = index;
    }
    
    // Auto-advance every 4 seconds
    setInterval(() => {
      const next = (currentSlide + 1) % totalSlides;
      goToSlide(next);
    }, 4000);
    
    // Click on dots
    dots.forEach((dot, index) => {
      dot.addEventListener('click', () => goToSlide(index));
    });
  }

  // Lazy load images if any
  const lazyImages = document.querySelectorAll('img[data-src]');
  if ('IntersectionObserver' in window) {
    const imageObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const img = entry.target;
          img.src = img.dataset.src;
          img.removeAttribute('data-src');
          observer.unobserve(img);
        }
      });
    });
    
    lazyImages.forEach(img => imageObserver.observe(img));
  }

  // Animate elements with data-animate attribute — IntersectionObserver for performance
  const animatedElements = document.querySelectorAll('[data-animate]');
  if (animatedElements.length > 0) {
    const animateObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          animateObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });
    
    animatedElements.forEach(el => animateObserver.observe(el));
  }
});

