/* Adinkra Symbol Popups */
document.addEventListener('DOMContentLoaded', function() {
  const symbolWraps = document.querySelectorAll('.adinkra-symbol-wrap');
  
  symbolWraps.forEach(wrap => {
    const name = wrap.getAttribute('data-name');
    
    if (name) {
      const popup = document.createElement('div');
      popup.className = 'adinkra-popup';
      popup.innerHTML = '<div class="adinkra-popup-name">' + name + '</div>';
      wrap.appendChild(popup);
    }
  });
});
